from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}  # id -> dict(patient, doctor, start, end, cancelled)
        self._next_id = 1

    def _is_active_slot(self, appt: dict) -> bool:
        """An appointment blocks its time slot unless it was cancelled
        at least 24 hours before its start."""
        if not appt["cancelled"]:
            return True
        return appt["cancel_blocked"]

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment starting in the past.")
        if end <= start:
            raise ValueError("Appointment end must be after start.")

        # Rule 2: at most one upcoming (non-cancelled, still-active) appointment per patient.
        for appt in self._appointments.values():
            if appt["patient"] == patient and self._is_active_slot(appt) and appt["end"] > now:
                raise ValueError(
                    f"Patient {patient!r} already has an upcoming appointment."
                )

        # Rule 3: no overlapping appointments for the same doctor.
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._is_active_slot(appt):
                continue
            if start < appt["end"] and appt["start"] < end:
                raise ValueError(
                    f"Doctor {doctor!r} is not available in that time range."
                )

        appt_id = self._next_id
        self._next_id += 1
        self._appointments[appt_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            # Only meaningful once cancelled: True if the slot stays blocked.
            "cancel_blocked": False,
        }
        return appt_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        if appointment_id not in self._appointments:
            raise KeyError(f"Unknown appointment id: {appointment_id}")
        appt = self._appointments[appointment_id]
        if appt["cancelled"]:
            return  # idempotent
        appt["cancelled"] = True
        # Rule 1: if cancelled less than 24 hours before start, keep the slot blocked.
        if appt["start"] - now < timedelta(hours=24):
            appt["cancel_blocked"] = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        if end <= start:
            return False
        for appt in self._appointments.values():
            if appt["doctor"] != doctor:
                continue
            if not self._is_active_slot(appt):
                continue
            if start < appt["end"] and appt["start"] < end:
                return False
        return True
